    for (const b of level.boote || []) liste.push({ x:b.x, y:BODEN_Y, w:b.w, h:14, voll:false, boot:true });   // Tower Bridge: im Boot-Abschnitt trägt das Ruderboot die Figur auf Bodenhöhe
