    c.fillStyle = '#ffd93d'; c.beginPath(); c.moveTo(-18, -21); c.lineTo(-26, -20); c.lineTo(-18, -19); c.closePath(); c.fill();   // Schnabel
    c.fillStyle = '#18213a'; c.beginPath(); c.arc(-15, -22, 1.3, 0, Math.PI * 2); c.fill();
    c.restore();
