      if (auf < 1) filmFellmuetze(c, lerp(TBF.ich + 36, TBF.serg, auf), lerp(BODEN_Y - 70, BODEN_Y - 104, auf) - Math.sin(auf * Math.PI) * 40, 0.8, true);
