  /* Film: Bühne in Weltkoordinaten (Paradeplatz der Horse Guards, Big Ben links dahinter), Kamera je Szene mit sanftem Schwenk/Zoom */
  const FILM_BB = { x: 300, s: 1.25 }, FILM_TOR = 720, FILM_SGT = 585;
