    for (let k = 0; k < 7; k++) { c.fillStyle = k % 2 ? '#ffffff' : FR_ROT; c.beginPath(); c.moveTo(-74 + k * 21.2, -174); c.lineTo(-74 + (k + 1) * 21.2, -174); c.lineTo(-70 + (k + 1) * 21.2, -156); c.lineTo(-70 + k * 21.2, -156); c.fill(); }
