    for (const s of [-1, 1]) { c.strokeStyle = '#8b5e30'; c.lineWidth = 2.5; c.beginPath(); c.moveTo(s * 22, 0); c.lineTo(s * 22, -18); c.lineTo(s * 30, -18); c.moveTo(s * 30, 0); c.lineTo(s * 30, -34); c.stroke(); }
    c.restore();
