    c.strokeStyle = 'rgba(0,0,0,.12)'; c.lineWidth = 1; c.beginPath(); c.moveTo(-6, -58); c.lineTo(-7, -12); c.moveTo(7, -58); c.lineTo(8, -12); c.stroke();
    c.fillStyle = '#e8b98f'; c.beginPath(); c.roundRect(-4, -106, 8, 10, 2); c.fill();   // Hals
