    for (let r = 0; r < 3; r++) fensterReihe(c, -196, -86 + r * 27, 24, 16.4, 7, r === 0 ? 8 : 13);
    c.fillStyle = STEIN_HELL; c.fillRect(-58, -112, 116, 112); giebel(c, -52, 52, -112, 20, STEIN_DUNKEL);
