    c.fillStyle = '#c9bfa8'; c.fillRect(-40, -46, 80, 4); c.fillStyle = '#8a1a26'; c.fillRect(-16, -42, 32, 4);   // Balkon mit rotem Tuch
    c.fillStyle = 'rgba(40,40,40,.6)'; c.beginPath(); c.roundRect(-10, -28, 20, 28, [10, 10, 0, 0]); c.fill();   // Tor
