      c.fillStyle = 'rgba(220,245,255,.8)'; for (let k = 0; k < 6; k++) { const f = ((t * 1.4 + k / 6) % 1), sx = k % 2 ? 1 : -1; c.beginPath(); c.arc(bx + sx * lerp(4, 34, f), -34 - h + f * (h + 30) - Math.sin(f * Math.PI) * 14, 1.6, 0, Math.PI * 2); c.fill(); }
