    c.fillStyle = '#d9b23a'; c.beginPath(); c.arc(0, -332, 5, 0, Math.PI * 2); c.fill(); c.fillRect(-1.5, -350, 3, 16); c.fillRect(-6, -345, 12, 3);
    c.fillStyle = st; c.fillRect(-150, -170, 300, 170);
