    if (o.licht) { c.save(); c.globalAlpha = 0.25 * o.licht; c.fillStyle = '#ffd27a'; c.beginPath(); c.ellipse(x, y - 150 * s, 80 * s, 190 * s, 0, 0, Math.PI * 2); c.fill(); c.restore(); }
