    c.fillStyle = '#cdbd99'; c.fillRect(x - w / 2 - 3 * s, y - 78 * s, w + 6 * s, 5 * s); c.fillRect(x - w / 2 - 2 * s, y - h, w + 4 * s, 4 * s);
