    if (o.muetze === 'koch') { c.fillStyle = '#fff'; c.fillRect(-7, -66, 14, 7); c.beginPath(); c.arc(-4, -68, 5, 0, Math.PI * 2); c.arc(4, -68, 5, 0, Math.PI * 2); c.arc(0, -71, 5, 0, Math.PI * 2); c.fill(); }
