        spielertunnel: (level.deko || []).filter((d) => d.art === 'spielertunnel').map((d) => ({ x: d.x, w: d.w })), toilette: (level.deko || []).filter((d) => d.art === 'toilette').map((d) => d.x), federn: (level.deko || []).filter((d) => d.art === 'federn').map((d) => d.x),
