          c.fillStyle = zeigOk ? 'rgba(56,193,114,.85)' : gew ? 'rgba(255,77,109,.75)' : 'rgba(255,255,255,.82)'; c.strokeStyle = '#3fa9f5'; c.lineWidth = 3;
