      if (s.kblase && kx < viewW + 40) blasePill(c, s.kblase.text, kx - 40, sy(BODEN_Y - 200), { gr: 13, bg: '#eaffea', spitze: [kx - 6, sy(BODEN_Y - 160)] });
      // HUD: Frage oben, Zähler, Banner, Hinweis
